export function nextGeneration(liveCells: Cell[]): Cell[] {
  const liveCellKeys = new Set(liveCells.map(key));
  const liveNeighbourCount = (cell: Cell): number =>
    neighboursOf(cell).filter((neighbour) => liveCellKeys.has(key(neighbour)))
      .length;

  // A cell can only change state if it is live or adjacent to a live one,
  // which keeps the grid effectively infinite without scanning it.
  const cellsThatCouldChange = liveCells.flatMap((liveCell) => [
    liveCell,
    ...neighboursOf(liveCell),
  ]);
  const candidates = new Map(
    cellsThatCouldChange.map((cell) => [key(cell), cell] as const),
  );

  return [...candidates].filter(([cellKey, cell]) =>
    isAliveNextGeneration(liveCellKeys.has(cellKey), liveNeighbourCount(cell)),
  ).map(([, cell]) => cell);
}

